// Illustrative sample project. EVERYTHING here is synthetic: the brands are fictional, all
// domains are reserved example.* domains, and every observation is generated by a seeded
// pseudo-random process. None of it is a real AI-assistant answer or citation.
// Pure and deterministic: the same seed always yields the same project.

import { detectBrandMentions } from './model.js';

export const SAMPLE_SEED = 20261019;
export const SAMPLE_PROJECT_ID = 'p-sample-ledgerly';
export const SAMPLE_NOTE = 'SYNTHETIC - illustrative only, not a real AI result';

/** mulberry32: small deterministic PRNG returning floats in [0, 1). */
export function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const SAMPLE_BRANDS = [
  { id: 'b-ledgerly', name: 'Ledgerly (fictional)', role: 'target', domains: ['ledgerly.example.com'], aliases: ['Ledgerly'] },
  { id: 'b-billbright', name: 'BillBright (fictional)', role: 'competitor', domains: ['billbright.example.com'], aliases: ['BillBright'] },
  { id: 'b-invoicenest', name: 'InvoiceNest (fictional)', role: 'competitor', domains: ['invoicenest.example.net'], aliases: ['InvoiceNest'] },
  { id: 'b-paytrail', name: 'PayTrail (fictional)', role: 'competitor', domains: ['paytrail.example.org'], aliases: ['PayTrail'] },
];

const Q = [
  // discovery (8)
  ['discovery', 'What are the best invoicing tools for freelancers?'],
  ['discovery', 'Which invoicing software works well for small agencies?'],
  ['discovery', 'What invoicing apps support recurring billing for subscriptions?'],
  ['discovery', 'Recommend invoicing software for a two-person consultancy.'],
  ['discovery', 'What tools can send invoices and chase late payments automatically?'],
  ['discovery', 'Which invoicing platforms handle multiple currencies?'],
  ['discovery', 'What is a good invoicing app for tradespeople who work on site?'],
  ['discovery', 'Which invoicing tools integrate with common accounting software?'],
  // informational (8)
  ['informational', 'How do I create a professional invoice?'],
  ['informational', 'What should be included on an invoice for a freelance project?'],
  ['informational', 'How can I reduce late payments from clients?'],
  ['informational', 'What is the difference between an invoice and a receipt?'],
  ['informational', 'How do automatic payment reminders work?'],
  ['informational', 'How should a small business number its invoices?'],
  ['informational', 'What do invoice payment terms like net 30 mean?'],
  ['informational', 'How do I handle deposits and partial payments on invoices?'],
  // comparison (7)
  ['comparison', 'Ledgerly vs BillBright: which is better for freelancers?'],
  ['comparison', 'How does InvoiceNest compare with Ledgerly for agencies?'],
  ['comparison', 'BillBright or PayTrail for recurring invoices?'],
  ['comparison', 'What are the main alternatives to BillBright?'],
  ['comparison', 'Which is cheaper for a small team: Ledgerly, InvoiceNest or PayTrail?'],
  ['comparison', 'Compare invoicing tools by ease of use for non-accountants.'],
  ['comparison', 'What are the pros and cons of PayTrail?'],
  // purchase (7)
  ['purchase', 'Is Ledgerly worth paying for?'],
  ['purchase', 'How much does Ledgerly cost per month?'],
  ['purchase', 'Which invoicing software has a free plan for one user?'],
  ['purchase', 'Can I import my client list into Ledgerly from a spreadsheet?'],
  ['purchase', 'What is the best invoicing software to buy for a growing agency?'],
  ['purchase', 'Does BillBright offer a discount for annual billing?'],
  ['purchase', 'Which invoicing tool should I choose if I need card payments on invoices?'],
];

export const SAMPLE_QUESTIONS = Q.map(([intent, text], i) => ({ id: `q${String(i + 1).padStart(2, '0')}`, text, intent, notes: '' }));

export const SAMPLE_PLATFORMS = ['Assistant A', 'Assistant B', 'Assistant C'];
export const SAMPLE_DATES = ['2026-09-07', '2026-10-05'];

const THIRD_PARTY = [
  'reviewhub.example.org',
  'smbtoolsguide.example.net',
  'freelancerforum.example.com',
  'accountingbasics.example.org',
  'smallbizdesk.example.net',
];

// Synthetic mention probabilities by intent, per brand (target first).
const P_MENTION = {
  discovery: { 'b-ledgerly': 0.42, 'b-billbright': 0.7, 'b-invoicenest': 0.5, 'b-paytrail': 0.32 },
  informational: { 'b-ledgerly': 0.1, 'b-billbright': 0.16, 'b-invoicenest': 0.1, 'b-paytrail': 0.06 },
  comparison: { 'b-ledgerly': 0.45, 'b-billbright': 0.55, 'b-invoicenest': 0.42, 'b-paytrail': 0.38 },
  purchase: { 'b-ledgerly': 0.4, 'b-billbright': 0.42, 'b-invoicenest': 0.3, 'b-paytrail': 0.22 },
};
const PLATFORM_MULT = { 'Assistant A': 1.0, 'Assistant B': 0.8, 'Assistant C': 1.1 };
const PLATFORM_CITES = { 'Assistant A': 0.85, 'Assistant B': 0.45, 'Assistant C': 0.9 };
// Synthetic drift on the second date for the target brand, so the date comparison has something to show.
const TARGET_DRIFT = { 'Assistant A': 0.1, 'Assistant B': 0.02, 'Assistant C': 0 };

// Which (platform, date, run) cells exist. Assistant C has no first-date data by design, to
// demonstrate how missing combinations are surfaced instead of imputed.
const CELLS = [
  { platform: 'Assistant A', date: '2026-09-07', run: 1 },
  { platform: 'Assistant B', date: '2026-09-07', run: 1 },
  { platform: 'Assistant A', date: '2026-10-05', run: 1 },
  { platform: 'Assistant B', date: '2026-10-05', run: 1 },
  { platform: 'Assistant C', date: '2026-10-05', run: 1 },
  // Repeated run for discovery questions only, to demonstrate run-to-run agreement.
  { platform: 'Assistant A', date: '2026-10-05', run: 2, intents: ['discovery'] },
];

const slug = (text) => text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 48);

/** Build the illustrative sample project (deterministic). */
export function buildSampleProject(seed = SAMPLE_SEED) {
  const rnd = mulberry32(seed);
  const brands = SAMPLE_BRANDS.map((b) => ({ ...b, domains: [...b.domains], aliases: [...b.aliases] }));
  const questions = SAMPLE_QUESTIONS.map((q) => ({ ...q }));
  const observations = [];
  let seq = 0;
  for (const cell of CELLS) {
    for (const q of questions) {
      if (cell.intents && !cell.intents.includes(q.intent)) continue;
      const named = detectBrandMentions(q.text, brands);
      const mentioned = [];
      for (const b of brands) {
        let p = P_MENTION[q.intent][b.id] * PLATFORM_MULT[cell.platform];
        if (b.role === 'target' && cell.date === SAMPLE_DATES[1]) p += TARGET_DRIFT[cell.platform];
        if (named.includes(b.id)) p = 0.97; // a brand named in the question is almost always discussed
        if (rnd() < Math.min(p, 0.98)) mentioned.push(b.id);
      }
      const citedUrls = [];
      const citedDomains = [];
      if (rnd() < PLATFORM_CITES[cell.platform]) {
        for (const id of mentioned) {
          const b = brands.find((x) => x.id === id);
          if (rnd() < (b.role === 'target' ? 0.45 : 0.4)) {
            const sub = rnd() < 0.3 ? 'help.' : '';
            citedUrls.push(`https://${sub}${b.domains[0]}/${q.intent === 'purchase' ? 'pricing' : 'features'}`);
          }
        }
        const k = 1 + Math.floor(rnd() * 2);
        for (let i = 0; i < k; i += 1) {
          const d = THIRD_PARTY[Math.floor(rnd() * THIRD_PARTY.length)];
          // Assistant B sometimes names a source without linking it: logged as a domain only.
          if (cell.platform === 'Assistant B' && rnd() < 0.5) { if (!citedDomains.includes(d)) citedDomains.push(d); } else {
            const url = `https://${d}/${q.intent}/${slug(q.text)}`;
            if (!citedUrls.includes(url)) citedUrls.push(url);
          }
        }
      }
      const names = mentioned.map((id) => brands.find((b) => b.id === id).aliases[0]);
      const sources = citedUrls.length + citedDomains.length;
      const answerSummary = names.length
        ? `Synthetic summary: ${q.intent} answer naming ${names.join(', ')}; ${sources ? `shows ${sources} source(s)` : 'no sources shown'}.`
        : `Synthetic summary: general ${q.intent} guidance with no tracked brand named; ${sources ? `shows ${sources} source(s)` : 'no sources shown'}.`;
      seq += 1;
      observations.push({
        id: `o${String(seq).padStart(3, '0')}`,
        questionId: q.id,
        platform: cell.platform,
        date: cell.date,
        run: cell.run,
        prompt: q.text,
        settings: 'Illustrative: default model, new chat, signed out, locale en-GB',
        answerSummary,
        brandsMentioned: mentioned,
        citedUrls,
        citedDomains,
        notes: SAMPLE_NOTE,
      });
    }
  }
  return {
    id: SAMPLE_PROJECT_ID,
    name: 'Ledgerly (fictional) — invoicing software visibility study',
    description: 'Illustrative sample project. Ledgerly and its competitors are fictional brands on example.* domains. '
      + 'Observations are synthetic, generated by a seeded random process — they are NOT real AI-assistant results.',
    illustrative: true,
    createdAt: '2026-10-19T00:00:00.000Z',
    brands,
    questions,
    observations,
  };
}
